"""Audit retained display/macro intent from immutable writers and original target bytes.
Usage: python check-retained-display-intent.py REPO PACKET_COMMIT NEW_OUTPUT
Read-only inputs. Does not execute historical geometry writers or change geometry.
"""
import gzip, hashlib, json, pathlib, subprocess, sys
from shapely.geometry import shape
W=pathlib.Path(sys.argv[1]); H=subprocess.check_output(['git','-C',str(W),'rev-parse',sys.argv[2]+'^{commit}']).decode().strip()
P='coordination/engineering/russia-repair-delivery-20261017/'; BASE='9d564cf4083cb5499b00d6fb4ceb6fc724fdf01c'
def raw(path,commit=BASE):return subprocess.check_output(['git','-c','protocol.allow=never','-C',str(W),'show',commit+':'+path])
def digest(v):return hashlib.sha256(json.dumps(v,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def pin(path,commit=BASE):
 b=raw(path,commit);return {'commit':commit,'path':path,'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'git_blob_oid':subprocess.check_output(['git','-C',str(W),'rev-parse',commit+':'+path]).decode().strip()}
stages=json.loads(raw(P+'source-stage/original-stage-inputs.json',H));assert len(stages)==334
receipt_path='data/macro-boundary-migration.json.gz';receipt=json.loads(gzip.decompress(raw(receipt_path)));assert receipt['summary']['geometry_changes']==0 and receipt['summary']['historical_records_touched']==0 and receipt['reference_only'] is True and receipt['historical_claims_transferred'] is False
changed={r['location_id']:r for r in receipt['changed_location_properties']};topology=[];repair=[];macro=[]
for row in stages:
 target=row['selected'];source=row['consumed'];ident=row['target'];m=target['properties']['metadata'];assert shape(target['geometry']).is_valid and shape(source['geometry']).is_valid
 base={'target':ident,'name':target['properties']['name'],'selected_geometry_custody_sha256':digest(target['geometry']),'consumed_geometry_custody_sha256':digest(source['geometry'])}
 if m.get('topology_reconciled'):
  original_hash=m['original_geometry_sha256'];raw_source_hash=hashlib.sha256(json.dumps(source['geometry'],sort_keys=True).encode()).hexdigest()
  assert original_hash!=raw_source_hash
  topology.append(base|{'metadata':{k:m[k] for k in ['topology_reconciled','topology_conflicts','topology_note','original_geometry_sha256']},'stored_pre_topology_display_hash_equals_consumed_source_geometry':False})
 if m.get('display_geometry_repaired'):repair.append(base|{'display_geometry_repaired':True,'consumed_source_valid':True,'selected_display_valid':True,'retained_scale_review':m.get('scale_review')})
 if m.get('macro_boundary_assignment'):
  proof=changed[ident];assert proof['geometry_sha256']==digest(target['geometry']);assert proof['after_properties']['metadata']['macro_boundary_assignment']==m['macro_boundary_assignment'];assert proof['history_transfer']=='none' and m['macro_boundary_assignment']['reference_only'] is True
  macro.append(base|{'metadata':m['macro_boundary_assignment'],'migration_geometry_sha256':proof['geometry_sha256'],'current_geometry_equals_migration_geometry_hash':True,'history_transfer':'none'})
assert len(topology)==177 and len(repair)==1 and repair[0]['target']=='gb:RUS:ADM2:50074027B96103137717036' and len(macro)==9
out={'version':1,'original_target_count':334,'stage_input':pin(P+'source-stage/original-stage-inputs.json',H),'method_pins':[pin(p) for p in ['scripts/prepare.mjs','scripts/repair-geometries.py','scripts/reconcile-topology.py','scripts/apply-macro-boundary-decisions.py']], 'macro_migration_receipt':pin(receipt_path),'geometry_hash_representation':'SHA-256 of Python json.dumps(geometry, ensure_ascii=False, sort_keys=True, separators=(comma,colon)), without newline. This custody comparison is not native valueSha identity.', 'topology':{'count':177,'targets':topology,'disposition':'A real retained display partition: shared intersections follow Natural Earth reference borders, then finer polygon/stable-ID priority. Nonoverlapping coastlines are explicitly preserved. No competing-source coverage may be restored. Full original same-family membership and all applicable complete foreign negatives constrain candidate native cells; the native patch may only fill owner-zero cells that qualify uniquely. Stored original_geometry_sha256 hashes bind pre-topology display geometry, after mapshaper simplification/precision and display repair, not raw consumed source geometry. The earlier display partition is retained, not reversed or replaced.'},'display_repair':{'count':1,'targets':repair,'disposition':'The pinned prepare writer first simplifies the display to 25 percent with keep-shapes and 0.0001 precision; the repair writer then uses polygonal MakeValid/union only on invalid or empty display geometry before topology. It does not change source identity or hierarchy. The marker is a display validity repair, not a deliberate geographic subdivision. Both consumed full source and retained selected display are valid. This package does not rerun historical repair, replace selected display geometry, or repair source input. The original invalid intermediate is not reconstructed, so no claim is made that its repair equals the full source.'},'macro_assignment':{'count':9,'targets':macro,'retained_receipt_summary':receipt['summary'],'disposition':'All nine whole-location Ural assignments are reference-only parent/metadata changes. The writer asserts unchanged geometry for every location, the original receipt reports zero geometry/history changes, and all nine selected geometry hashes still equal the immutable migration receipt. No geographic slicing or historical transfer is implied. This package neither recomputes majority shares nor certifies present legal role, descendant semantics, or a changed macro convention.'},'limits':['Original display convention, selected geometry, hierarchy, source identities and metadata remain unchanged.','Native source-relative gap qualification is not a reconstruction of every earlier display operation or an adjudication of territorial sovereignty.','Topology and display-repair flags are not grouping labels; their distinct intent and limitations are retained.']}
with pathlib.Path(sys.argv[3]).open('x') as f:json.dump(out,f,ensure_ascii=False,sort_keys=True,separators=(',',':'));f.write('\n')
print(json.dumps({'targets':334,'topology_partition_targets':177,'display_repair_targets':1,'macro_reference_only_targets':9,'all_nine_macro_geometry_hashes_equal_original_receipt':True,'all_177_pre_topology_display_hashes_distinct_from_consumed_source':True}))
